"""
Python script to detect land use type (urban, agriculture, forest, unknown) 
for coordinates in Denmark using OpenStreetMap data via Overpass API.
"""

import requests
import time
import random
from typing import Optional, Tuple

# Multiple Overpass API endpoints to distribute load
OVERPASS_ENDPOINTS = [
    "http://overpass-api.de/api/interpreter",
    "https://overpass.kumi.systems/api/interpreter",
    "https://overpass.openstreetmap.ru/api/interpreter",
]

# Urban categories - built environment and human settlements
URBAN_LANDUSE = [
    'residential',      # Housing areas
    'commercial',       # Business and commercial zones
    'industrial',       # Manufacturing and industrial areas
    'retail',           # Shopping and retail zones
    'military',         # Military installations
    'quarry',           # Mining/quarrying sites
    'warehouse',        # Storage and warehouse facilities
    'port',             # Port areas
    'brownfield',       # Previously developed land
    'landfill',         # Waste disposal sites
    'construction',     # Active construction sites
    'garages',          # Parking garages
    'parking',          # Parking areas
    'cemetery',         # Burial grounds
    'religious',        # Religious sites
    'school',           # Educational facilities
    'university',       # University campuses
    'college',          # College campuses
    'public',           # Public facilities
    'recreation_ground', # Recreational areas (urban)
    'village_green',    # Village greens (urban context)
    'square',           # Public squares
    'plaza',            # Plazas
    'pedestrian',       # Pedestrian zones
    'salt_pond',        # Industrial salt production
    'depot',            # Transport depots
    'railway',          # Railway facilities
    'harbour',          # Harbor areas
    'logistics',        # Logistics centers
    'storage',          # Storage facilities
]

# Agriculture categories - farming and cultivation
AGRICULTURE_LANDUSE = [
    'farmland',             # General agricultural land
    'farmyard',             # Farm buildings and yards
    'orchard',              # Fruit tree orchards
    'vineyard',             # Grape cultivation
    'meadow',               # Grassland for hay/harvesting
    'greenhouse_horticulture', # Greenhouse farming
    'pasture',              # Grazing land
    'grass',                # Grassland (agricultural)
    'agricultural',         # General agricultural use
    'paddy',                # Rice paddies
    'plant_nursery',        # Plant nurseries
    'allotments',           # Community garden plots
    'flowerbed',            # Flower cultivation
    'greenfield',           # Undeveloped agricultural land
]

# Forest categories - woodland and natural vegetation
FOREST_LANDUSE = [
    'forest',               # Managed forests
    'wood',                 # Woodland areas
]

FOREST_NATURAL = [
    'wood',                 # Natural woodland
    'forest',               # Natural forest
    'tree_row',             # Rows of trees
    'scrub',                # Scrubland (woody vegetation)
    'heath',                # Heathland (can be forested)
    'moor',                 # Moorland (often with trees)
    'wetland',              # Wetlands (can be forested)
    'shoal',                # Sandbank or sandbar (natural feature)
]

def query_land_use(lat: float, lon: float, max_retries: int = 5) -> Tuple[str, str]:
    """
    Query OpenStreetMap via Overpass API to determine land use type.
    Includes retry logic with exponential backoff for rate limiting.
    
    Args:
        lat: Latitude coordinate
        lon: Longitude coordinate
        max_retries: Maximum number of retry attempts
        
    Returns:
        Tuple of (result, reason) where:
        - result: 'urban', 'agriculture', 'forest', or 'unknown'
        - reason: Explanation for the result, especially if 'unknown'
    """
    # Query to get land use information around the point
    # We query a larger area (500m radius) around the point for better coverage
    # Includes multiple tag types for comprehensive detection
    query = f"""[out:json][timeout:15];
(
  way["landuse"](around:500,{lat},{lon});
  relation["landuse"](around:500,{lat},{lon});
  way["natural"](around:500,{lat},{lon});
  relation["natural"](around:500,{lat},{lon});
  way["leisure"](around:500,{lat},{lon});
  relation["leisure"](around:500,{lat},{lon});
  way["place"](around:500,{lat},{lon});
  node["place"](around:500,{lat},{lon});
);
out tags;"""
    
    # Try multiple endpoints with retries
    for attempt in range(max_retries):
        # Rotate through endpoints
        endpoint_idx = attempt % len(OVERPASS_ENDPOINTS)
        overpass_url = OVERPASS_ENDPOINTS[endpoint_idx]
        
        try:
            if attempt > 0:
                print(f"  Attempt {attempt + 1}/{max_retries}...", end=' ', flush=True)
            else:
                print("  Querying API...", end=' ', flush=True)
            
            response = requests.get(overpass_url, params={'data': query}, timeout=30)
            
            # Handle rate limiting (429) with exponential backoff
            if response.status_code == 429:
                wait_time = (2 ** attempt) + random.uniform(0, 1)  # Exponential backoff with jitter
                if attempt < max_retries - 1:
                    print(f"\n  Rate limited (429). Waiting {wait_time:.1f}s before retry {attempt + 1}/{max_retries}...", flush=True)
                    time.sleep(wait_time)
                    continue
                else:
                    reason = "API error: Max retries reached due to rate limiting (429)"
                    print(f"\n  {reason}", flush=True)
                    return ('unknown', reason)
            
            response.raise_for_status()
            data = response.json()
            
            if not data.get('elements'):
                reason = "No data: API returned no elements (no landuse/natural/leisure/place tags found in 500m radius)"
                return ('unknown', reason)
            
            # Check for land use tags
            land_uses = set()
            found_tags = []  # Track what tags we found for debugging
            for element in data.get('elements', []):
                tags = element.get('tags', {})
                landuse = tags.get('landuse', '')
                natural = tags.get('natural', '')
                leisure = tags.get('leisure', '')
                place = tags.get('place', '')
                
                # Track found tags
                if landuse:
                    found_tags.append(f"landuse={landuse}")
                if natural:
                    found_tags.append(f"natural={natural}")
                if leisure:
                    found_tags.append(f"leisure={leisure}")
                if place:
                    found_tags.append(f"place={place}")
                
                # Check urban categories
                if landuse in URBAN_LANDUSE:
                    land_uses.add('urban')
                # Urban leisure areas (parks, sports facilities, etc. in urban context)
                elif leisure in ['park', 'sports_centre', 'stadium', 'pitch', 'playground', 'golf_course', 'swimming_pool', 'fitness_centre', 'marina', 'beach_resort']:
                    land_uses.add('urban')
                # Urban place types
                elif place in ['city', 'town', 'village', 'hamlet', 'suburb', 'neighbourhood', 'quarter', 'city_block']:
                    land_uses.add('urban')
                # Check agriculture categories
                elif landuse in AGRICULTURE_LANDUSE:
                    land_uses.add('agriculture')
                # Check forest categories (both landuse and natural tags)
                elif landuse in FOREST_LANDUSE or natural in FOREST_NATURAL:
                    land_uses.add('forest')
                # Natural leisure areas (nature reserves, etc.)
                elif leisure in ['nature_reserve', 'nature_park']:
                    land_uses.add('forest')
            
            # Return the first match (priority: urban > agriculture > forest)
            if 'urban' in land_uses:
                return ('urban', "Category matched: urban")
            elif 'agriculture' in land_uses:
                return ('agriculture', "Category matched: agriculture")
            elif 'forest' in land_uses:
                return ('forest', "Category matched: forest")
            else:
                # No matching category found
                if found_tags:
                    unique_tags = ', '.join(set(found_tags))
                    reason = f"Category not in list: Found tags ({unique_tags}) but none match our categories"
                else:
                    reason = "Category not in list: Elements found but no landuse/natural tags present"
                return ('unknown', reason)
                
        except requests.exceptions.Timeout:
            if attempt < max_retries - 1:
                wait_time = (2 ** attempt) + random.uniform(0, 1)
                print(f"\n  Timeout. Waiting {wait_time:.1f}s before retry {attempt + 1}/{max_retries}...", flush=True)
                time.sleep(wait_time)
                continue
            else:
                reason = f"API error: Timeout after {max_retries} attempts"
                print(f"\n  {reason}. Returning 'unknown'.", flush=True)
                return ('unknown', reason)
        except requests.exceptions.RequestException as e:
            if attempt < max_retries - 1:
                wait_time = (2 ** attempt) + random.uniform(0, 1)
                print(f"\n  Request error: {str(e)[:50]}. Waiting {wait_time:.1f}s before retry {attempt + 1}/{max_retries}...", flush=True)
                time.sleep(wait_time)
                continue
            else:
                reason = f"API error: Request failed after {max_retries} attempts - {str(e)[:100]}"
                print(f"\n  {reason}", flush=True)
                return ('unknown', reason)
        except Exception as e:
            reason = f"API error: Unexpected error - {str(e)[:100]}"
            print(f"\n  {reason}", flush=True)
            return ('unknown', reason)
    
    reason = "API error: All retry attempts exhausted"
    return ('unknown', reason)


