    print("=" * 60)
    print("Land Use Detection for Coordinates")
    print("=" * 60)
    print(f"Processing {len(coordinates)} coordinates...\n")
    
    results = []
    for idx, coord in enumerate(coordinates, 1):
        lat, lon = coord
        print(f"[{idx}/{len(coordinates)}] Processing: Latitude={lat}, Longitude={lon}")
        
        result, reason = query_land_use(lat, lon)
        results.append({
            'latitude': lat,
            'longitude': lon,
            'land_use': result,
            'reason': reason
        })
        
        print(f"  Result: {result}")
        if result == 'unknown':
            print(f"  Reason: {reason}")
        print()
        
        # Add delay between requests to respect API rate limits
        if idx < len(coordinates):
            delay = random.uniform(3, 5)
            print(f"  Waiting {delay:.1f}s before next request...\n")
            time.sleep(delay)
    
    # Print summary
    print("=" * 60)
    print("SUMMARY")
    print("=" * 60)
    for idx, result in enumerate(results, 1):
        print(f"{idx}. ({result['latitude']}, {result['longitude']}) -> {result['land_use']}")
        if result['land_use'] == 'unknown':
            print(f"    Reason: {result['reason']}")
    print("=" * 60)
    
    # Write results to text file
    output_file = "results.txt"
    print(f"\nWriting results to {output_file}...")
    with open(output_file, 'w', encoding='utf-8') as f:
        for result in results:
            # Format: one result per line
            f.write(f"{result['land_use']}\n")
    print(f"Results saved to {output_file}")

